// Reference solution
function countTouches(signInAt, requestTimes, touchEveryMs) {
  var lastSeen = signInAt, n = 0;
  for (var i = 0; i < requestTimes.length; i++) {
    if (requestTimes[i] - lastSeen >= touchEveryMs) { lastSeen = requestTimes[i]; n++; }
  }
  return n;
}
